// secstore — encrypted key-value store using ChaCha20-Poly1305
// Backend: file
// KDF: pbkdf2, key size: 32, hash: sha256

fn derive_key::(password, salt) {
    let iterations = 100000;
    return @crypto_pbkdf2(password, @base64(salt), iterations, 32);
}

fn encrypt_json::(obj, key) {
    let plain = @bytes(@json_encode(obj));
    let mem = @mem_from_bytes(plain);
    @mem_encrypt(mem, key);
    let cipher = @mem_to_bytes(mem);
    @free(mem);
    return @base64(cipher);
}

fn decrypt_json::(cipher_b64, key) {
    let cipher = @base64_decode(cipher_b64);
    let mem = @mem_from_bytes(cipher);
    @mem_decrypt(mem, key);
    let plain = @mem_to_string(mem);
    @free(mem);
    return @json_decode(plain);
}

fn open_store::(path, password) {
    let salt = null;
    let data = null;
    if (@exists(path)) {
        let raw = @read_text(path);
        let env = @json_decode(raw);
        salt = env["salt"];
        data = env["data"];
    } else {
        salt = @base64(@crypto_random_bytes(16));
        data = encrypt_json({}, derive_key(password, @base64_decode(salt)));
    }
    let key = derive_key(password, @base64_decode(salt));
    return {"path": path, "salt": salt, "data": data, "key": key};
}

fn save_store::(store) {
    let env = {"salt": store["salt"], "data": store["data"]};
    @write_text(store["path"], @json_encode(env));
    return true;
}

fn get_key::(store, key) {
    let obj = decrypt_json(store["data"], store["key"]);
    if (@map_has_key(obj, key)) { return obj[key]; }
    return null;
}

fn set_key::(store, key, value) {
    let obj = decrypt_json(store["data"], store["key"]);
    obj[key] = value;
    store["data"] = encrypt_json(obj, store["key"]);
    save_store(store);
    return value;
}

fn delete_key::(store, key) {
    let obj = decrypt_json(store["data"], store["key"]);
    let existed = @map_has_key(obj, key);
    if (existed) {
        obj = @map_omit_keys(obj, [key]);
        store["data"] = encrypt_json(obj, store["key"]);
        save_store(store);
    }
    return existed;
}

fn keys_of::(store) {
    let obj = decrypt_json(store["data"], store["key"]);
    return @map_keys_sorted(obj);
}

fn size_of::(store) {
    let obj = decrypt_json(store["data"], store["key"]);
    return @len(obj);
}

fn rotate_password::(store, new_password) {
    let obj = decrypt_json(store["data"], store["key"]);
    let new_salt = @crypto_random_bytes(16);
    store["salt"] = @base64(new_salt);
    store["key"] = derive_key(new_password, new_salt);
    store["data"] = encrypt_json(obj, store["key"]);
    save_store(store);
    return true;
}

fn version::() { return "1.0.0"; }
